solution.solution.cpp:
#include <cstddef>
#include <cstdint>

struct StoneApi
{
    uint32_t size;
    uint32_t version;
    int32_t (*add)(int32_t, int32_t);
    int32_t (*multiply)(int32_t, int32_t);
    int32_t (*power)(int32_t, int32_t);
};

namespace
{
    int32_t addImpl(int32_t a, int32_t b) { return a + b; }
    int32_t multiplyImpl(int32_t a, int32_t b) { return a * b; }
    int32_t powerImpl(int32_t b, int32_t e)
    {
        if (e < 0) return 0;
        int32_t r{ 1 };
        for (int32_t i{ 0 }; i < e; ++i) r *= b;
        return r;
    }
    const StoneApi g_api{ sizeof(StoneApi), 2, addImpl, multiplyImpl, powerImpl };
}

const StoneApi* getStoneApi(uint32_t wantedVersion)
{
    if (wantedVersion == 0 || wantedVersion > 2) return nullptr;
    return &g_api;
}

int32_t powerOrFallback(const StoneApi* api, int32_t base, int32_t exponent)
{
    if (!api) return 0;
    const bool hasPower{ api->version >= 2 && api->size >= offsetof(StoneApi, power) + sizeof(api->power) && api->power };
    if (hasPower) return api->power(base, exponent);
    int32_t r{ 1 };
    for (int32_t i{ 0 }; i < exponent; ++i) r = api->multiply(r, base);
    return r;
}

unitTests:
TEST("versions offered") { CHECK(getStoneApi(1) != nullptr); CHECK(getStoneApi(2) != nullptr); CHECK(getStoneApi(3) == nullptr); CHECK(getStoneApi(0) == nullptr); }
TEST("the table") { const StoneApi* a = getStoneApi(2); CHECK_EQ(a->version, 2u); CHECK_EQ(a->size, static_cast<uint32_t>(sizeof(StoneApi))); CHECK_EQ(a->add(2, 3), 5); CHECK_EQ(a->multiply(4, 5), 20); CHECK_EQ(a->power(2, 10), 1024); CHECK_EQ(a->power(5, 0), 1); CHECK_EQ(a->power(2, -1), 0); }
TEST("caller uses power when present") { CHECK_EQ(powerOrFallback(getStoneApi(1), 3, 4), 81); }
int32_t timesTwoLie(int32_t a, int32_t b) { return a * b; }
int32_t brokenPower(int32_t, int32_t) { return -999; }
TEST("caller falls back for an old table") {
    StoneApi old{ static_cast<uint32_t>(offsetof(StoneApi, power)), 1, nullptr, timesTwoLie, brokenPower };
    CHECK_EQ(powerOrFallback(&old, 3, 4), 81);
    StoneApi labelledNew{ static_cast<uint32_t>(offsetof(StoneApi, power)), 2, nullptr, timesTwoLie, brokenPower };
    CHECK_EQ(powerOrFallback(&labelledNew, 2, 3), 8);
}
TEST("null table") { CHECK_EQ(powerOrFallback(nullptr, 2, 2), 0); }

